  const [kind, code] = String(boardId || "").split(":");
  if (kind !== "AOA" || !BOARD_TASKS[`AOA:${code}`]?.disciplines) return false;
  return effectiveBoardSpecialties(data).some(id => id.startsWith(`AOA-SUB:${code}:`));
