/**
 * The tasks for one board card, each with:
 *   status: "done" (marked in this period), "not-required" (the physician
 *           said it is not required for them this period: answered, never
 *           alerted), "unconfirmed" (the date passed with no mark: asked,
 *           never alerted),
 *           "upcoming" (the window has not opened), "not-yet" (the board has
 *           not started it for this certificate), or "due"
 *   due, daysLeft (null when the board has not published a date), doneOn,
 *   notRequiredOn, field (where a mark is stored), period label, and
 *   periodWord ("year" or "cycle"), markable (false for a step with no
 *   period the app can place: no mark is offered), askFirst (an unmarked
 *   step in the first period the app tracks it: asked, never alerted), and
 *   startsWhy for a "not-yet" step ("expiration" or "newIssue").
 * With the board's valid-thru facts (validThruFor), where to check and who
 * to ask.
 * Null when the board has no task data.
 */
export function boardTasksFor(data, board, now = new Date()) {
  const boardId = board?.id;
  const set = boardTaskSet(boardId);
  if (!set || shadowedByDiscipline(data, boardId)) return null;
  const record = boardRecordFor(data?.licenses, boardId);
  const parentId = sharedParentId(data, boardId);
  const marks = boardTaskMarks(data, parentId ? boardRecordFor(data?.licenses, parentId) : null, record);
  const today = localToday(now);
  const tasks = set.tasks.map(task => {
    const period = taskPeriod(task, now, record);
    const field = boardTaskField(boardId, task, period.label);
    // The parent card's mark for the same duty counts here too (and Undo clears it).
    const alsoFields = parentId ? [boardTaskField(parentId, task, period.label)] : [];
    const mark = [field, ...alsoFields].map(f => readMark(marks[f])).find(Boolean) || null;
    const doneOn = mark?.kind === "done" ? mark.on : null;
    const notRequiredOn = mark?.kind === "not-required" ? mark.on : null;
    const starts = startsYear(task, boardId, record);
    const begins = starts?.year || null;
    let status = "due";
    if (doneOn) status = "done";
    else if (notRequiredOn) status = "not-required";
    else if (begins && begins > now.getFullYear()) status = "not-yet";
    // Past the date with no mark: the app cannot tell a missed step from one
    // done before it was tracked here, so it asks instead of alarming
    // (2026-11-18: every unmarked ABNS task read overdue on day one).
    else if (period.due && today > period.due) status = "unconfirmed";
    else if (period.opens && today < period.opens) status = "upcoming";
    return {
      id: task.id, label: task.label, detail: task.detail || "", cost: task.cost ?? null, source: task.source || set.sourceUrl,
      dueRule: period.due ? "" : (task.dueRule || (task.every?.anchor === "certExpiration" ? "By your certificate's expiration date. Add that date to the board certification record to see it here." : "")),
      every: task.every, period: period.label, due: period.due, opens: period.opens,
      daysLeft: period.due ? daysUntilDate(period.due, now) : null,
      doneOn, notRequiredOn, status, field, alsoFields, startsYear: begins && begins > now.getFullYear() ? begins : null,
      startsWhy: begins && begins > now.getFullYear() ? starts.why : null,
      periodWord: task.every === "year" ? "year" : "cycle",
      // A mark needs a period that ends; an existing one still shows (and Undo clears it).
      markable: period.label !== UNPLACED_PERIOD,
      askFirst: status === "due" && inFirstTrackedPeriod(task, set, period, record),
    };
  });
  return {
    boardId, recordId: record?.id || null, tasks, validThru: validThruFor(boardId, record),
    whereToCheck: set.whereToCheck || null, contact: set.contact || null,
    checked: set.checked, sourceUrl: set.sourceUrl,
  };
}

/**
 * A mark written as the physician chose it, on the board's Board
 * Certification record: a Done date (ISO) or notRequiredMark(day). `date`
 * null removes it (Undo) wherever it is: the
 * record, any record holding a shared parent-card mark (`alsoFields`), and a
 * legacy settings.boardTaskMarks copy. Returns, for the caller to save:
 *   records:  edited existing records (editItem)
 *   create:   a new Board Certification record carrying the mark, when none
 *             is on file (addItem)
 *   settings: { boardTaskMarks } with the legacy copy cleared, when it held one
 */
export function applyBoardTaskMark(data, boardId, field, date, { alsoFields = [], makeId } = {}) {
  const fields = [field, ...alsoFields];
  const marking = !!readMark(date);
  const strip = (obj) => {
    const out = { ...(obj || {}) };
    for (const f of fields) delete out[f];
    return out;
  };
  const has = (obj) => !!obj && fields.some(f => Object.prototype.hasOwnProperty.call(obj, f));
  const own = boardRecordFor(data?.licenses, boardId);
  const records = [];
  for (const l of data?.licenses || []) {
    if (!l) continue;
    const mine = own && l.id === own.id;
    if (!(mine && marking) && !has(l.customFields)) continue;
    const customFields = strip(l.customFields);
    if (mine && marking) customFields[field] = date;
    const rec = { ...l, customFields };
    // A record the 11-18 release made carried noExpiration ("Does not
    // expire"); the first write the physician makes through the card moves
    // it to the app's marker, so the form no longer shows that box ticked.
    if (awaitsBoardDate(l) && !l.customFields?.[BOARD_APP_MADE_FIELD]) {
      rec.noExpiration = false;
      rec.customFields[BOARD_APP_MADE_FIELD] = "Added when you marked a board step";
    }
    records.push(rec);
  }
  const out = { records };
  if (marking && !own) {
    const rec = newBoardRecord(boardId, makeId);
    out.create = { ...rec, customFields: { ...rec.customFields, [field]: date } };
  }
  const legacy = data?.settings?.boardTaskMarks;
  if (has(legacy)) out.settings = { boardTaskMarks: strip(legacy) };
  return out;
}

/**
 * Board tasks that belong in the alerts (the bell, the banner, the reminder
 * message, the reminder email): due inside the reminder lead window. A date
 * that passed with no mark is asked on the card, never alerted. A task with no
 * published date, already done, marked not required, or not started yet
 * raises nothing, and so does a step in the first period the app tracks it
 * (askFirst: asked on the card instead, see inFirstTrackedPeriod).
 * [{ board, tasks }] per board with any, tasks as boardTasksFor gives them.
 * boardTaskAlerts makes the app's one entry per board from it; the reminder
 * email (supabase/functions/_shared/reminderBoardSteps.mjs) names each task.
 */
export function openBoardTasks(data, boards, lead, now = new Date()) {
  const out = [];
  for (const b of boards || []) {
    if (b.followsParent || b.source === "CERT" || b.body) continue;
    const t = boardTasksFor(data, b, now);
    if (!t) continue;
    const open = t.tasks.filter(x => x.status === "due" && !x.askFirst && x.daysLeft != null && x.daysLeft >= 0 && x.daysLeft <= lead);
    if (open.length) out.push({ board: b, tasks: open });
  }
  return out;
}

/** The alert entries for openBoardTasks: one per board, as the CME gaps list them. */
export function boardTaskAlerts(data, boards, lead, now = new Date()) {
  return openBoardTasks(data, boards, lead, now).map(({ board: b, tasks: open }) => {
    const issues = open.map(x => `${x.label}: due ${x.due}`);
    const soonest = open.reduce((a, x) => (x.due < a.due ? x : a), open[0]);
    return { state: b.code, issues, daysLeft: soonest.daysLeft, renewal: soonest.due, key: `board:${b.id}`, kind: "board", label: b.label };
  });
}

/**
 * Every dated board step still ahead: status "due" or "upcoming" with a due
 * date on or after today, on every board card that has task data (the same
 * cards openBoardTasks reads). A step that is done, marked not required, past
 * its date with no mark ("unconfirmed") or not started yet for this
 * certificate is left out. Each is listed with its date like a dated
 * credential, wherever the app lists deadlines (the Notification Center's
 * upcoming list, Home search, Vera), however far off it is.
 * `alerted` is true for a step inside the reminder lead window, which
 * openBoardTasks already alerts; the rest are listed, never alerted.
 * Sorted by due date. [{ boardId, boardLabel, taskId, label, name, due,
 * opens, daysLeft, status, period, periodWord, source, askFirst, alerted }]
 */
export function datedBoardSteps(data, boards, lead, now = new Date()) {
  const alerted = new Set();
  for (const { board, tasks } of openBoardTasks(data, boards, lead, now)) for (const x of tasks) alerted.add(`${board.id}|${x.id}`);
  const out = [];
  for (const b of boards || []) {
    if (b.followsParent || b.source === "CERT" || b.body) continue;
    const t = boardTasksFor(data, b, now);
    if (!t) continue;
    for (const x of t.tasks) {
      if (x.status !== "due" && x.status !== "upcoming") continue;
      if (!x.due || !ISO.test(x.due) || x.daysLeft == null || x.daysLeft < 0) continue;
      out.push({
        boardId: b.id, boardLabel: b.label || certName(b.id), taskId: x.id, label: x.label,
        name: boardTaskName(b.id, x), due: x.due, opens: x.opens, daysLeft: x.daysLeft, status: x.status,
        period: x.period, periodWord: x.periodWord, source: x.source, askFirst: !!x.askFirst, alerted: alerted.has(`${b.id}|${x.id}`),
      });
    }
  }
  return out.sort((a, b) => a.due.localeCompare(b.due) || a.name.localeCompare(b.name));
}

/** The dated board steps outside the alerts: listed as upcoming deadlines, never alerted. */
export function upcomingBoardSteps(data, boards, lead, now = new Date()) {
  return datedBoardSteps(data, boards, lead, now).filter(s => !s.alerted);
}
